-- Athena saved query (Product_B2C_Intl)
-- ID: 13301aa7-636e-488c-bfc4-6b3ea3d65a7b
-- Name: Toilet tag Coverage History Data Overall - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH sl AS ( SELECT mri_session_id, route_id, MAX(op_id) AS operator_id, MAX(__time) AS sl_time FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-07-10 18:30:00' AND __time < TIMESTAMP '2026-07-21 18:30:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' GROUP BY 1, 2 ), route_flags AS ( SELECT DISTINCT srd.route_id FROM user_interaction.search_route_details srd WHERE srd.__time >= TIMESTAMP '2026-07-10 18:30:00' AND srd.__time < TIMESTAMP '2026-07-21 18:30:00' AND CONTAINS(srd.persuasion_id, '537') AND srd.route_id IN (SELECT DISTINCT route_id FROM sl) ), ui_joined AS ( SELECT u.event_src, u.mri_session_id, u.event_group, u.event_name, sl.route_id, CASE WHEN rf.route_id IS NOT NULL THEN 1 ELSE 0 END AS toilet_route_id FROM user_interaction.ui_ux_events u INNER JOIN sl ON sl.mri_session_id = u.mri_session_id AND sl.sl_time BETWEEN u.__time - INTERVAL '1' SECOND AND u.__time + INTERVAL '1' SECOND LEFT JOIN route_flags rf ON rf.route_id = sl.route_id WHERE u.__time >= TIMESTAMP '2026-07-10 18:30:00' AND u.__time < TIMESTAMP '2026-07-21 18:30:00' AND u.header_bu = 'BUS' AND u.header_country = 'IND' AND UPPER(u.event_src) = 'ANDROID' AND ( u.event_group = 'sl_screen_load' OR (u.event_group = 'sl_click_info' AND u.event_name = 'ToiletShown') ) AND ( (UPPER(u.event_src) = 'ANDROID' AND u.app_code >= 821000) OR (UPPER(u.event_src) = 'IOS' AND u.app_code >= 862200) ) ), ui_metrics AS ( SELECT COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' THEN mri_session_id END) AS sl_load_sessions, COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' AND toilet_route_id = 1 THEN mri_session_id END) AS toilet_tag_sl_sessions, COUNT(DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'ToiletShown' THEN mri_session_id END) AS toilet_shown_sl_sessions FROM ui_joined ), sl_ui_keys AS ( SELECT DISTINCT mri_session_id, route_id, toilet_route_id FROM ui_joined ), txn_metrics AS ( SELECT COUNT(DISTINCT bte.tin) AS txn_count, COUNT(DISTINCT CASE WHEN k.toilet_route_id = 1 THEN bte.tin END) AS toilet_tag_tins FROM sl_ui_keys k LEFT JOIN transaction.bus_ticket_events bte ON k.mri_session_id = bte.mri_session_id AND k.route_id = bte.route_id AND bte.event_type = 101 AND bte.country_code = 'IND' AND bte.time_of_event >= TIMESTAMP '2026-07-10 18:30:00' AND bte.time_of_event < TIMESTAMP '2026-07-21 18:30:00' ) SELECT 'Jul 11 to 21' AS doi, u.sl_load_sessions, u.toilet_tag_sl_sessions, u.toilet_shown_sl_sessions, COALESCE(t.txn_count, 0) AS txn_count, COALESCE(t.toilet_tag_tins, 0) AS toilet_tag_tins -- , -- 1.0 * u.toilet_tag_sl_sessions / NULLIF(u.sl_load_sessions, 0) AS toilet_tag_sl_pct FROM ui_metrics u CROSS JOIN txn_metrics t;
